insert into formateurs (id, slug, nom, expertise, bio, programme_principal, photo, fiche_complete, coaching_prive_fcfa_heure, coaching_prive_actif, seo_mot_cle_principal, seo_title, seo_meta_description, seo_og_title, seo_og_description, seo_og_image, seo_canonical, seo_indexable) values
  ('for-declercq', 'jeremie-de-clercq', 'Jérémie De Clercq', 'Stratégie business & entrepreneuriat', 'Jérémie De Clercq intervient sur les modules consacrés à la structuration des fondamentaux d’une activité : modèle économique, coûts, prix et lecture du marché. Il accompagne des entrepreneurs et des équipes marketing en Afrique francophone.', 'entrepreneurs', '/images/formateurs/jeremie-de-clercq.svg', true, 50000, false, null, null, null, null, null, null, null, true),
  ('for-othniel', 'coury-othniel', 'Coury Othniel', 'Copywriting & contenu', 'Copywriter spécialisé dans les contenus qui retiennent l’attention sur les réseaux sociaux en Afrique francophone. Il anime les modules de rédaction persuasive des deux programmes.', 'social-media', '/images/formateurs/coury-othniel.svg', true, 50000, true, null, null, null, null, null, null, null, true),
  ('for-waffo', 'kevine-waffo', 'Kevine Waffo', 'Stratégie social media & ciblage', 'Kevine Waffo construit des plans d’action social media pour des marques et des institutions : diagnostic, ciblage, planning éditorial et pilotage des publications.', 'social-media', '/images/formateurs/kevine-waffo.svg', true, 50000, true, null, null, null, null, null, null, null, true),
  ('for-cocou', 'emmanuel-cocou', 'Emmanuel Cocou', 'Offres & positionnement', 'Emmanuel Cocou aide les entrepreneurs à transformer une compétence en offre lisible : périmètre, promesse, livrables et argumentaire de vente.', 'entrepreneurs', '/images/formateurs/emmanuel-cocou.svg', true, 50000, false, null, null, null, null, null, null, null, true),
  ('for-nontondji', 'maurice-nontondji', 'Maurice Nontondji', 'LinkedIn : algorithme & prospection', 'Maurice Nontondji travaille la visibilité professionnelle sur LinkedIn : compréhension de l’algorithme, formats de publication et prospection directe.', 'social-media', '/images/formateurs/maurice-nontondji.svg', true, 50000, false, null, null, null, null, null, null, null, true),
  ('for-soboro', 'lyle-soboro', 'Lyle Soboro', 'Vente, TikTok & acquisition client', 'Lyle Soboro accompagne des vendeurs et des commerces dans l’acquisition client sans site web : WhatsApp Business, TikTok et tunnels de vente simples.', 'entrepreneurs', '/images/formateurs/lyle-soboro.svg', true, 50000, true, null, null, null, null, null, null, null, true),
  ('for-akinocho', 'nouroudine-akinocho', 'Nouroudine Akinocho', 'Visibilité & croissance en ligne', 'Nouroudine Akinocho intervient sur la visibilité en ligne des petites structures : référencement local, présence sur les plateformes et croissance organique.', 'entrepreneurs', '/images/formateurs/nouroudine-akinocho.svg', true, 50000, false, null, null, null, null, null, null, null, true);
insert into modules (id, slug, numero, titre, programme, thematique_id, formateur_id, promesse, pourquoi, pour_qui, prerequis, acquis, livrable, faq, duree_minutes, prix_fcfa, statut, publie_le, seo_mot_cle_principal, seo_title, seo_meta_description, seo_og_title, seo_og_description, seo_og_image, seo_canonical, seo_indexable) values
  ('mod-comprendre-le-business-du-client', 'comprendre-le-business-du-client', 1, 'Comprendre le business du client', 'social-media', 'th-sm-fondations', 'for-declercq', 'Apprenez à lire l’activité d’une marque avant de produire le moindre contenu, pour proposer une stratégie qui sert ses objectifs.', 'Un contenu peut être soigné et régulier sans rien apporter à l’entreprise qui le publie. Ce module vous donne la grille de lecture qui permet de comprendre un modèle économique, ses marges et ses priorités, puis d’en déduire ce que le social media doit réellement produire.', array['Vous gérez les réseaux sociaux d’une marque ou de plusieurs clients.', 'Vos recommandations sont difficiles à défendre en réunion.', 'Vous souhaitez relier vos contenus aux objectifs commerciaux.']::text[], 'Aucun prérequis particulier.', array['analyser le modèle économique d’une marque ;', 'identifier ses priorités commerciales ;', 'formuler des objectifs social media alignés.']::text[], 'Une fiche de cadrage client réutilisable pour chaque nouvelle marque ou chaque nouveau projet.', '[{"question":"La session de coaching collectif est-elle comprise dans le prix ?","reponse":"Oui. L’achat donne accès aux sessions liées à la thématique du module, selon le calendrier et les places disponibles. Votre fiche apprenant devra être complétée avant votre participation."},{"question":"Puis-je revoir le module après l’avoir terminé ?","reponse":"Oui. Vous conservez un accès à vie au module depuis votre espace apprenant."}]'::jsonb, 60, 10000, 'disponible', '2026-06-01', null, null, null, null, null, null, null, true),
  ('mod-plan-daction-social-media-strategie-et-ciblage', 'plan-daction-social-media-strategie-et-ciblage', 2, 'Plan d’action social media : Stratégie & Ciblage', 'social-media', 'th-sm-fondations', 'for-waffo', 'Construisez un plan d’action social media qui part d’une cible précise plutôt que d’une intuition.', 'Publier pour « tout le monde » revient à ne parler à personne. Ce module structure le diagnostic, le choix de la cible et les axes stratégiques qui en découlent, avec des arbitrages assumés.', array['Vous démarrez sur un nouveau compte ou une nouvelle marque.', 'Vos publications touchent une audience trop large ou mal qualifiée.', 'Vous devez présenter une stratégie à un décideur.']::text[], 'Aucun prérequis particulier.', array['poser un diagnostic factuel ;', 'définir une cible exploitable ;', 'construire un plan d’action argumenté.']::text[], 'Un plan d’action social media sur une page, prêt à être présenté.', '[{"question":"La session de coaching collectif est-elle comprise dans le prix ?","reponse":"Oui. L’achat donne accès aux sessions liées à la thématique du module, selon le calendrier et les places disponibles. Votre fiche apprenant devra être complétée avant votre participation."},{"question":"Puis-je revoir le module après l’avoir terminé ?","reponse":"Oui. Vous conservez un accès à vie au module depuis votre espace apprenant."}]'::jsonb, 60, 10000, 'disponible', '2026-06-01', null, null, null, null, null, null, null, true),
  ('mod-plan-daction-social-media-planning-editorial', 'plan-daction-social-media-planning-editorial', 3, 'Plan d’action social media : Planning éditorial', 'social-media', 'th-sm-fondations', 'for-waffo', 'Transformez une stratégie en planning tenable, avec des formats et un rythme que vous pourrez réellement soutenir.', 'La régularité échoue rarement par manque d’idées : elle échoue par manque de système. Ce module installe un planning éditorial calibré sur vos moyens réels de production.', array['Vous publiez de façon irrégulière.', 'Vous manquez d’idées en fin de mois.', 'Vous travaillez seul ou avec une petite équipe.']::text[], 'Avoir défini une cible et des axes stratégiques.', array['construire un planning éditorial mensuel ;', 'choisir des formats adaptés à ses moyens ;', 'anticiper la production de contenu.']::text[], 'Un planning éditorial mensuel complété et une banque d’idées de départ.', '[{"question":"La session de coaching collectif est-elle comprise dans le prix ?","reponse":"Oui. L’achat donne accès aux sessions liées à la thématique du module, selon le calendrier et les places disponibles. Votre fiche apprenant devra être complétée avant votre participation."},{"question":"Puis-je revoir le module après l’avoir terminé ?","reponse":"Oui. Vous conservez un accès à vie au module depuis votre espace apprenant."}]'::jsonb, 60, 10000, 'disponible', '2026-06-01', null, null, null, null, null, null, null, true),
  ('mod-formules-de-redaction-persuasive', 'formules-de-redaction-persuasive', 4, 'Formules de rédaction persuasive', 'social-media', 'th-sm-copywriting', 'for-othniel', 'Appliquez des structures de rédaction éprouvées pour écrire plus vite des messages qui portent.', 'Devant une page blanche, la qualité dépend du temps disponible. Les formules de rédaction suppriment cette dépendance : elles donnent une ossature au message et libèrent l’attention pour le fond.', array['Vous écrivez régulièrement pour les réseaux sociaux.', 'Vos textes manquent de structure ou de chute.', 'Vous voulez réduire votre temps de rédaction.']::text[], 'Aucun prérequis particulier.', array['utiliser plusieurs structures de rédaction ;', 'adapter une formule à son contexte ;', 'réécrire un texte de façon méthodique.']::text[], 'Un carnet de formules annotées et adaptées à votre activité.', '[{"question":"La session de coaching collectif est-elle comprise dans le prix ?","reponse":"Oui. L’achat donne accès aux sessions liées à la thématique du module, selon le calendrier et les places disponibles. Votre fiche apprenant devra être complétée avant votre participation."},{"question":"Puis-je revoir le module après l’avoir terminé ?","reponse":"Oui. Vous conservez un accès à vie au module depuis votre espace apprenant."}]'::jsonb, 60, 10000, 'disponible', '2026-06-01', null, null, null, null, null, null, null, true),
  ('mod-accroches-qui-stoppent-le-scroll-et-ia-copywriting', 'accroches-qui-stoppent-le-scroll-et-ia-copywriting', 5, 'Accroches qui stoppent le scroll & IA copywriting', 'social-media', 'th-sm-copywriting', 'for-othniel', 'Apprenez à construire plus rapidement des accroches capables de retenir l’attention, avec une méthode claire et l’IA comme assistant.', 'Une publication peut être utile, bien conçue et correctement ciblée sans retenir l’attention si son ouverture manque d’impact. Ce module vous aide à structurer vos premiers mots, varier vos angles et produire plus rapidement sans déléguer votre réflexion à l’IA.', array['Vous gérez les réseaux sociaux d’une marque ou de plusieurs clients.', 'Vos contenus peinent à retenir l’attention.', 'Vous souhaitez produire plus rapidement sans sacrifier la qualité.']::text[], 'Aucun prérequis particulier. La méthode est expliquée et appliquée progressivement pendant le module.', array['reconnaître les éléments qui rendent une accroche plus efficace ;', 'produire plusieurs propositions rapidement ;', 'utiliser l’IA pour enrichir la réflexion et varier les angles.']::text[], 'Une bibliothèque personnelle de 30 accroches adaptées à votre secteur, accompagnée d’une routine de travail pour produire plus rapidement de nouvelles propositions avec l’aide de l’IA.', '[{"question":"Ai-je besoin d’un outil d’IA payant ?","reponse":"Non. Le module ne dépend pas d’un outil payant particulier. Les fonctionnalités nécessaires et les différentes options sont présentées pendant le module."},{"question":"La méthode peut-elle s’appliquer à tous les secteurs ?","reponse":"Oui. Les principes enseignés sont adaptables à différents secteurs. Les exercices vous permettent de travailler directement à partir de votre activité, de votre marque ou de vos clients."},{"question":"La session de coaching collectif est-elle comprise dans le prix ?","reponse":"Oui. L’achat donne accès aux sessions liées à la thématique du module, selon le calendrier et les places disponibles. Votre fiche apprenant devra être complétée avant votre participation."},{"question":"Puis-je revoir le module après l’avoir terminé ?","reponse":"Oui. Vous conservez un accès à vie au module depuis votre espace apprenant."}]'::jsonb, 60, 10000, 'disponible', '2026-06-01', null, null, null, null, null, null, null, true),
  ('mod-creer-un-buzz-sur-les-reseaux-sociaux', 'creer-un-buzz-sur-les-reseaux-sociaux', 6, 'Créer un buzz sur les réseaux sociaux', 'social-media', 'th-sm-copywriting', 'for-othniel', 'Comprenez ce qui déclenche réellement la circulation d’un contenu, et ce qu’il est raisonnable d’en attendre.', 'Le buzz n’est pas un objectif de communication : c’est une conséquence. Ce module démonte les mécaniques de diffusion et distingue ce qui se pilote de ce qui relève du hasard.', array['Vous travaillez sur une marque grand public.', 'On vous demande régulièrement « du viral ».', 'Vous souhaitez arbitrer entre visibilité et réputation.']::text[], 'Aucun prérequis particulier.', array['identifier les ressorts de diffusion ;', 'concevoir un contenu partageable ;', 'anticiper les risques de réputation.']::text[], 'Une grille d’évaluation des risques et opportunités avant publication.', '[{"question":"La session de coaching collectif est-elle comprise dans le prix ?","reponse":"Oui. L’achat donne accès aux sessions liées à la thématique du module, selon le calendrier et les places disponibles. Votre fiche apprenant devra être complétée avant votre participation."},{"question":"Puis-je revoir le module après l’avoir terminé ?","reponse":"Oui. Vous conservez un accès à vie au module depuis votre espace apprenant."}]'::jsonb, 60, 10000, 'en-preparation', null, null, null, null, null, null, null, null, false),
  ('mod-linkedin-algorithme-et-prospection', 'linkedin-algorithme-et-prospection', 7, 'LinkedIn : algorithme & prospection', 'social-media', 'th-sm-plateformes', 'for-nontondji', 'Utilisez LinkedIn comme un canal de prospection, pas seulement comme une vitrine professionnelle.', 'LinkedIn récompense des comportements précis. Ce module explique ce que la plateforme valorise, puis construit une routine de publication et de prise de contact qui tient en trente minutes par jour.', array['Vous vendez à des professionnels.', 'Votre profil reçoit peu de visites.', 'Vos prises de contact restent sans réponse.']::text[], 'Disposer d’un profil LinkedIn actif.', array['optimiser son profil ;', 'publier des formats adaptés ;', 'structurer une séquence de prise de contact.']::text[], 'Une séquence de prospection en cinq messages, prête à personnaliser.', '[{"question":"La session de coaching collectif est-elle comprise dans le prix ?","reponse":"Oui. L’achat donne accès aux sessions liées à la thématique du module, selon le calendrier et les places disponibles. Votre fiche apprenant devra être complétée avant votre participation."},{"question":"Puis-je revoir le module après l’avoir terminé ?","reponse":"Oui. Vous conservez un accès à vie au module depuis votre espace apprenant."}]'::jsonb, 60, 10000, 'disponible', '2026-06-01', null, null, null, null, null, null, null, true),
  ('mod-instagram-formats-et-croissance', 'instagram-formats-et-croissance', 8, 'Instagram : formats et croissance', 'social-media', 'th-sm-plateformes', 'for-nontondji', 'Choisissez les formats Instagram qui font réellement progresser un compte, et abandonnez les autres.', 'Chaque format Instagram sert un objectif différent. Ce module cartographie les formats disponibles, leur coût de production et leur effet mesuré sur la croissance.', array['Vous animez un compte Instagram professionnel.', 'Votre croissance stagne malgré la régularité.', 'Vous hésitez entre les formats.']::text[], 'Disposer d’un compte professionnel Instagram.', array['choisir un format selon son objectif ;', 'produire un format court au téléphone ;', 'lire les statistiques de son compte.']::text[], 'Un plan de production hebdomadaire calibré sur vos moyens.', '[{"question":"La session de coaching collectif est-elle comprise dans le prix ?","reponse":"Oui. L’achat donne accès aux sessions liées à la thématique du module, selon le calendrier et les places disponibles. Votre fiche apprenant devra être complétée avant votre participation."},{"question":"Puis-je revoir le module après l’avoir terminé ?","reponse":"Oui. Vous conservez un accès à vie au module depuis votre espace apprenant."}]'::jsonb, 60, 10000, 'disponible', '2026-06-01', null, null, null, null, null, null, null, true),
  ('mod-publicite-sociale-lancer-sa-premiere-campagne', 'publicite-sociale-lancer-sa-premiere-campagne', 9, 'Publicité sociale : lancer sa première campagne', 'social-media', 'th-sm-plateformes', 'for-soboro', 'Lancez une première campagne payante maîtrisée, avec un budget contenu et un résultat mesurable.', 'La publicité sociale amplifie ce qui fonctionne déjà et gaspille tout le reste. Ce module suit une campagne réelle du cadrage jusqu’à la lecture des résultats.', array['Vous n’avez jamais lancé de campagne payante.', 'Vos précédentes campagnes n’ont pas été mesurées.', 'Vous disposez d’un budget limité.']::text[], 'Disposer d’une page professionnelle active.', array['paramétrer une campagne complète ;', 'construire une audience pertinente ;', 'interpréter un rapport de performance.']::text[], 'Un modèle de brief de campagne et une grille de lecture des résultats.', '[{"question":"La session de coaching collectif est-elle comprise dans le prix ?","reponse":"Oui. L’achat donne accès aux sessions liées à la thématique du module, selon le calendrier et les places disponibles. Votre fiche apprenant devra être complétée avant votre participation."},{"question":"Puis-je revoir le module après l’avoir terminé ?","reponse":"Oui. Vous conservez un accès à vie au module depuis votre espace apprenant."}]'::jsonb, 60, 10000, 'disponible', '2026-06-01', null, null, null, null, null, null, null, true),
  ('mod-valider-son-idee-de-business-avant-dinvestir', 'valider-son-idee-de-business-avant-dinvestir', 1, 'Valider son idée de business avant d’investir', 'entrepreneurs', 'th-ent-fondations', 'for-declercq', 'Vérifiez qu’une idée répond à un besoin réel avant d’y engager du temps et de l’argent.', 'La majorité des projets échouent sur une hypothèse jamais vérifiée. Ce module transforme une intuition en série de tests simples, réalisables en quelques jours et sans budget.', array['Vous avez une idée que vous n’avez pas encore testée.', 'Vous hésitez à investir dans un premier stock ou un outil.', 'Vous voulez éviter de construire ce que personne n’achètera.']::text[], 'Aucun prérequis particulier.', array['formuler une hypothèse testable ;', 'concevoir un test rapide et peu coûteux ;', 'prendre une décision fondée sur des retours réels.']::text[], 'Un protocole de test complété, avec critères de décision définis à l’avance.', '[{"question":"La session de coaching collectif est-elle comprise dans le prix ?","reponse":"Oui. L’achat donne accès aux sessions liées à la thématique du module, selon le calendrier et les places disponibles. Votre fiche apprenant devra être complétée avant votre participation."},{"question":"Puis-je revoir le module après l’avoir terminé ?","reponse":"Oui. Vous conservez un accès à vie au module depuis votre espace apprenant."}]'::jsonb, 60, 10000, 'disponible', '2026-06-01', null, null, null, null, null, null, null, true),
  ('mod-fixer-le-juste-prix-de-ses-produits-et-services', 'fixer-le-juste-prix-de-ses-produits-et-services', 2, 'Fixer le juste prix de ses produits et services', 'entrepreneurs', 'th-ent-fondations', 'for-declercq', 'Apprenez à fixer un prix qui couvre vos coûts, valorise votre travail et reste cohérent avec votre marché.', 'Un prix trop faible fragilise votre marge, tandis qu’un prix mal aligné avec le marché peut freiner la vente. Ce module vous aide à sortir des décisions prises uniquement au feeling pour construire et défendre un prix fondé sur des éléments concrets.', array['Vous lancez ou gérez votre activité.', 'Vous ne connaissez pas précisément votre coût de revient.', 'Vous diminuez vos prix dès qu’un client négocie.', 'Vous souhaitez mieux défendre la valeur de votre offre.']::text[], 'Aucun prérequis particulier. Prévoyez simplement les informations disponibles sur vos coûts, vos charges et vos prix actuels.', array['calculer son coût de revient ;', 'choisir une stratégie de prix ;', 'présenter et défendre son prix avec davantage d’assurance.']::text[], 'Une grille tarifaire construite à partir des coûts réels et directement utilisable pour présenter ses prix aux clients.', '[{"question":"Dois-je déjà avoir lancé mon activité ?","reponse":"Non. Le module convient également aux porteurs de projet qui souhaitent construire leurs premiers prix sur des bases plus solides."},{"question":"Que faire si je ne connais pas encore tous mes coûts ?","reponse":"Le module vous aide à identifier les principales catégories à prendre en compte. Vous pourrez commencer avec les données disponibles, puis affiner progressivement vos calculs."},{"question":"La méthode fonctionne-t-elle pour les produits et les services ?","reponse":"Oui. Le module présente les éléments à considérer selon la nature de l’offre afin d’adapter le calcul et la stratégie de prix."},{"question":"La session de coaching collectif est-elle comprise dans le prix ?","reponse":"Oui. L’achat donne accès aux sessions liées à la thématique du module, selon le calendrier et les places disponibles. Votre fiche apprenant devra être complétée avant votre participation."},{"question":"Puis-je revoir le module après l’avoir terminé ?","reponse":"Oui. Vous conservez un accès à vie au module depuis votre espace apprenant."}]'::jsonb, 60, 10000, 'disponible', '2026-06-01', null, null, null, null, null, null, null, true),
  ('mod-structurer-une-offre-claire-qui-se-vend', 'structurer-une-offre-claire-qui-se-vend', 3, 'Structurer une offre claire qui se vend', 'entrepreneurs', 'th-ent-fondations', 'for-cocou', 'Passez d’une liste de compétences à une offre qu’un client comprend et peut acheter immédiatement.', 'Une offre floue se négocie toujours à la baisse. Ce module cadre le périmètre, le livrable, la promesse et le prix, puis construit l’argumentaire correspondant.', array['Vous proposez « un peu de tout ».', 'Vos devis donnent lieu à de longues discussions.', 'Vous souhaitez formaliser une offre reproductible.']::text[], 'Aucun prérequis particulier.', array['cadrer un périmètre ;', 'écrire une offre lisible ;', 'traiter les objections de prix.']::text[], 'Une fiche d’offre complète, prête à être envoyée à un prospect.', '[{"question":"La session de coaching collectif est-elle comprise dans le prix ?","reponse":"Oui. L’achat donne accès aux sessions liées à la thématique du module, selon le calendrier et les places disponibles. Votre fiche apprenant devra être complétée avant votre participation."},{"question":"Puis-je revoir le module après l’avoir terminé ?","reponse":"Oui. Vous conservez un accès à vie au module depuis votre espace apprenant."}]'::jsonb, 60, 10000, 'disponible', '2026-06-01', null, null, null, null, null, null, null, true),
  ('mod-trouver-ses-premiers-clients', 'trouver-ses-premiers-clients', 4, 'Trouver ses premiers clients', 'entrepreneurs', 'th-ent-vente', 'for-soboro', 'Mettez en place une routine de prospection simple qui produit des rendez-vous dès la première semaine.', 'Attendre que les clients viennent est la première cause d’arrêt d’activité. Ce module installe une méthode de prise de contact directe, adaptée aux réalités du marché local.', array['Vous démarrez votre activité.', 'Votre réseau proche est déjà épuisé.', 'La prospection vous met mal à l’aise.']::text[], 'Disposer d’une offre formulée.', array['constituer une liste de prospects ;', 'rédiger un message d’approche ;', 'suivre ses relances sans outil complexe.']::text[], 'Une liste de 50 prospects qualifiés et une séquence de messages prête à l’emploi.', '[{"question":"La session de coaching collectif est-elle comprise dans le prix ?","reponse":"Oui. L’achat donne accès aux sessions liées à la thématique du module, selon le calendrier et les places disponibles. Votre fiche apprenant devra être complétée avant votre participation."},{"question":"Puis-je revoir le module après l’avoir terminé ?","reponse":"Oui. Vous conservez un accès à vie au module depuis votre espace apprenant."}]'::jsonb, 60, 10000, 'disponible', '2026-06-01', null, null, null, null, null, null, null, true),
  ('mod-vendre-sans-site-web-whatsapp-business', 'vendre-sans-site-web-whatsapp-business', 5, 'Vendre sans site web : WhatsApp Business de A à Z', 'entrepreneurs', 'th-ent-vente', 'for-soboro', 'Transformez WhatsApp Business en véritable canal de vente, du catalogue jusqu’à la relance.', 'La majorité des ventes se concluent déjà sur WhatsApp, mais rarement de façon organisée. Ce module structure le catalogue, les réponses rapides, le suivi des commandes et les relances.', array['Vous vendez déjà via WhatsApp sans méthode.', 'Vous perdez des commandes dans le fil des conversations.', 'Vous n’avez pas de site et n’en voulez pas pour l’instant.']::text[], 'Disposer d’un numéro dédié à l’activité.', array['configurer WhatsApp Business ;', 'structurer une conversation de vente ;', 'organiser ses relances.']::text[], 'Un catalogue configuré et un jeu de réponses rapides adapté à votre activité.', '[{"question":"La session de coaching collectif est-elle comprise dans le prix ?","reponse":"Oui. L’achat donne accès aux sessions liées à la thématique du module, selon le calendrier et les places disponibles. Votre fiche apprenant devra être complétée avant votre participation."},{"question":"Puis-je revoir le module après l’avoir terminé ?","reponse":"Oui. Vous conservez un accès à vie au module depuis votre espace apprenant."}]'::jsonb, 60, 10000, 'disponible', '2026-06-01', null, null, null, null, null, null, null, true),
  ('mod-negocier-et-conclure-une-vente', 'negocier-et-conclure-une-vente', 6, 'Négocier et conclure une vente', 'entrepreneurs', 'th-ent-vente', 'for-cocou', 'Menez un entretien de vente jusqu’à la décision, sans céder systématiquement sur le prix.', 'Beaucoup d’entretiens se terminent par un « je vous rappelle ». Ce module donne une structure d’entretien et les formulations qui permettent de conclure ou d’obtenir un refus clair.', array['Vous vendez vous-même vos prestations.', 'Vos prospects reportent leur décision.', 'Vous acceptez trop souvent de baisser vos prix.']::text[], 'Avoir une offre et un prix définis.', array['conduire un entretien structuré ;', 'répondre aux objections courantes ;', 'obtenir une décision explicite.']::text[], 'Une trame d’entretien annotée et une liste d’objections avec leurs réponses.', '[{"question":"La session de coaching collectif est-elle comprise dans le prix ?","reponse":"Oui. L’achat donne accès aux sessions liées à la thématique du module, selon le calendrier et les places disponibles. Votre fiche apprenant devra être complétée avant votre participation."},{"question":"Puis-je revoir le module après l’avoir terminé ?","reponse":"Oui. Vous conservez un accès à vie au module depuis votre espace apprenant."}]'::jsonb, 60, 10000, 'disponible', '2026-06-01', null, null, null, null, null, null, null, true),
  ('mod-contenus-qui-attirent-des-clients', 'contenus-qui-attirent-des-clients', 7, 'Contenus qui attirent des clients', 'entrepreneurs', 'th-ent-visibilite', 'for-othniel', 'Produisez des contenus qui amènent des demandes entrantes plutôt que de simples félicitations.', 'Un contenu apprécié n’est pas un contenu qui vend. Ce module oriente la production vers les sujets qui déclenchent une prise de contact.', array['Vous publiez sans retombée commerciale.', 'Vous manquez de temps pour produire.', 'Vous voulez générer des demandes entrantes.']::text[], 'Aucun prérequis particulier.', array['choisir des sujets orientés demande ;', 'écrire un appel à la conversation ;', 'tenir un rythme de publication réaliste.']::text[], 'Une liste de 20 sujets à fort potentiel commercial pour votre activité.', '[{"question":"La session de coaching collectif est-elle comprise dans le prix ?","reponse":"Oui. L’achat donne accès aux sessions liées à la thématique du module, selon le calendrier et les places disponibles. Votre fiche apprenant devra être complétée avant votre participation."},{"question":"Puis-je revoir le module après l’avoir terminé ?","reponse":"Oui. Vous conservez un accès à vie au module depuis votre espace apprenant."}]'::jsonb, 60, 10000, 'disponible', '2026-06-01', null, null, null, null, null, null, null, true),
  ('mod-etre-visible-localement-sur-internet', 'etre-visible-localement-sur-internet', 8, 'Être visible localement sur internet', 'entrepreneurs', 'th-ent-visibilite', 'for-akinocho', 'Apparaissez dans les recherches locales de vos clients, sans budget publicitaire.', 'Une part importante des achats commence par une recherche locale. Ce module met en place les bases : fiche établissement, avis, cohérence des informations et présence sur les plateformes utiles.', array['Vous avez une activité avec une zone de chalandise.', 'Vos clients vous trouvent difficilement en ligne.', 'Vous n’avez pas de budget publicitaire.']::text[], 'Aucun prérequis particulier.', array['créer une fiche établissement complète ;', 'solliciter des avis clients ;', 'maintenir des informations cohérentes.']::text[], 'Une check-list de présence locale complétée pour votre activité.', '[{"question":"La session de coaching collectif est-elle comprise dans le prix ?","reponse":"Oui. L’achat donne accès aux sessions liées à la thématique du module, selon le calendrier et les places disponibles. Votre fiche apprenant devra être complétée avant votre participation."},{"question":"Puis-je revoir le module après l’avoir terminé ?","reponse":"Oui. Vous conservez un accès à vie au module depuis votre espace apprenant."}]'::jsonb, 60, 10000, 'disponible', '2026-06-01', null, null, null, null, null, null, null, true),
  ('mod-mesurer-ce-qui-fait-vraiment-avancer-son-activite', 'mesurer-ce-qui-fait-vraiment-avancer-son-activite', 9, 'Mesurer ce qui fait vraiment avancer son activité', 'entrepreneurs', 'th-ent-visibilite', 'for-akinocho', 'Suivez cinq indicateurs utiles plutôt que vingt tableaux que personne ne lit.', 'Sans mesure, chaque décision se prend au ressenti. Ce module sélectionne les indicateurs qui comptent réellement pour une petite structure et installe une routine de suivi hebdomadaire.', array['Vous ne savez pas quoi mesurer.', 'Vous accumulez des données sans les exploiter.', 'Vous voulez décider sur des faits.']::text[], 'Aucun prérequis particulier.', array['sélectionner ses indicateurs ;', 'construire un tableau de bord simple ;', 'installer une routine de revue.']::text[], 'Un tableau de bord d’une page, complété avec vos propres données.', '[{"question":"La session de coaching collectif est-elle comprise dans le prix ?","reponse":"Oui. L’achat donne accès aux sessions liées à la thématique du module, selon le calendrier et les places disponibles. Votre fiche apprenant devra être complétée avant votre participation."},{"question":"Puis-je revoir le module après l’avoir terminé ?","reponse":"Oui. Vous conservez un accès à vie au module depuis votre espace apprenant."}]'::jsonb, 60, 10000, 'disponible', '2026-06-01', null, null, null, null, null, null, null, true);
